package com.bookeat.payment.service;
import com.bookeat.payment.dto.*;import com.bookeat.payment.entity.Payment;import com.bookeat.payment.enums.*;import com.bookeat.payment.gateway.GatewayPort;import com.bookeat.payment.mapper.PaymentMapper;import com.bookeat.payment.repository.PaymentRepository;import com.bookeat.commerce.service.CommerceAccess;import com.bookeat.common.response.PageResponse;import com.bookeat.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import java.util.*;
@Service @RequiredArgsConstructor public class PaymentServiceImpl implements PaymentService {
 private final PaymentTransactions transactions;private final PaymentRepository payments;private final GatewayPort gateway;private final CommerceAccess access;private final PaymentMapper mapper;
 public PaymentResponses.View create(UUID actor,String key,PaymentRequests.Create q){UUID customer=access.customer(actor);var existing=payments.findFirstByCustomerIdAndReferenceTypeAndReferenceIdAndStatusInOrderByCreatedAtDesc(customer,q.referenceType(),q.referenceId(),java.util.List.of(PaymentStatus.CREATED,PaymentStatus.PENDING));if(existing.isPresent()){var prior=existing.get();if(prior.getGateway()==q.gateway())return mapper.view(prior);/* v26: allow an explicit payment-method switch. The old unpaid intent is abandoned so its payment lines no longer reserve the bill. */prior.setStatus(PaymentStatus.FAILED);prior.setFailureReason("Replaced by customer payment-method change");payments.saveAndFlush(prior);}UUID id=transactions.reserve(actor,key,q);var p=payments.findById(id).orElseThrow();if(p.getGateway()==PaymentGateway.RAZORPAY&&transactions.beginDispatch(id)){try{transactions.attachOrder(id,gateway.create(id,p.getAmount()));}catch(ApiException ex){transactions.uncertain(id);}}return get(actor,id);}
 public PaymentResponses.View verify(UUID actor,PaymentRequests.Verify q){var p=owned(actor,q.paymentId());transactions.requireGatewayContext(p);if(p.getGatewayOrderId()==null||!gateway.verifyCheckout(p.getGatewayOrderId(),q.gatewayPaymentId(),q.signature()))throw new ApiException(ErrorCode.PAYMENT_INVALID);var proof=gateway.fetchPayment(q.gatewayPaymentId());if(!q.gatewayPaymentId().equals(proof.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);transactions.capture(p.getId(),proof,actor);return get(actor,p.getId());}
 @Transactional(readOnly=true) public PaymentResponses.View get(UUID actor,UUID id){return mapper.view(owned(actor,id));}
 @Transactional(readOnly=true) public PageResponse<PaymentResponses.View> list(UUID actor,int page,int size){return PageResponse.from(payments.findByCustomerId(access.customer(actor),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(mapper::view));}
 public PaymentResponses.View reconcile(UUID id,String gatewaySessionId){var p=payments.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));transactions.requireGatewayContext(p);String sessionId=p.getGatewayOrderId()!=null?p.getGatewayOrderId():gatewaySessionId;if(!com.bookeat.payment.gateway.RazorpayPaymentsGateway.validId(sessionId)||gatewaySessionId!=null&&p.getGatewayOrderId()!=null&&!gatewaySessionId.equals(p.getGatewayOrderId()))throw new ApiException(ErrorCode.PAYMENT_RECONCILIATION_REQUIRED);var session=gateway.fetchSession(sessionId);transactions.attachOrder(id,session.order());for(String candidate:session.paymentIds()){var proof=gateway.fetchPayment(candidate);if("captured".equals(proof.status()))transactions.capture(id,proof,null);}return mapper.view(payments.findById(id).orElseThrow());}
 public PaymentResponses.View refresh(UUID actor,UUID id){var p=owned(actor,id);transactions.requireGatewayContext(p);return reconcile(id,null);}
 public PaymentResponses.View cash(UUID actor,UUID rid,UUID id,PaymentRequests.Action q){return mapper.view(transactions.cash(actor,rid,id,q));}
 private Payment owned(UUID actor,UUID id){return payments.findById(id).filter(p->p.getCustomerId().equals(access.customer(actor))).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));}
}
